{"type":"FlowTopic","triggers":[{"type":"Trigger","name":"297804a453d6442caa91ee66dc5886cc","triggerType":"request","applicability":{"type":"Applicability","mode":"script","value":"true"},"id":"297804a453d6442caa91ee66dc5886cc"}],"goals":[{"name":"primary","trigger_id":"297804a453d6442caa91ee66dc5886cc","nodes":[{"type":"StartGoal","goal_id":"primary","greeting_msg":{"type":"String","mode":"string","value":"gs.getMessageLang("va:topic:2900e4a72b3fee10d4dffd74ce91bfe8:node:873db8fa26ad4d9a8ecc32d3c3e226f6:field:GreetingMsg", vaContext.getRequesterLang())"},"id":"873db8fa26ad4d9a8ecc32d3c3e226f6","name":"Start","expert_mode":false},{"type":"TerminateGoal","goal_id":"primary","confirmation_msg":{"type":"String","mode":"string","value":"gs.getMessageLang("✅ User details check completed", vaContext.getRequesterLang())"},"id":"b8f27cef568f48cf8f1ea8206adfc78d","name":"End","expert_mode":false},{"type":"ScriptedAction","script":"(function execute() {

 var identityGr = new GlideRecordSecure("x_aleen_snguardian_identity");
 identityGr.addQuery('email', vaInputs.user_email);
 identityGr.addQuery('is_deleted', false);
 identityGr.query();
 if (identityGr.next()) {
 var user_type = identityGr.type.code;
 vaVars.guardian_user_sys_id = identityGr.sys_id.toString();
 vaVars.user_name = identityGr.full_name.toString();
 vaVars.user_photo = identityGr.photo.toString();
 vaVars.user_type = identityGr.type.name.toString();
 vaVars.user_type_sys_id = identityGr.type.toString();
 if (user_type == 'VISITOR') {
 var visitorGr = new GlideRecordSecure("x_aleen_snguardian_visitor");
 if (visitorGr.get(identityGr.sys_id)) {
 vaVars.user_status = visitorGr.visitor_status.name.toString();
 vaVars.user_number = visitorGr.number.toString();
 }
 } else {
 vaVars.user_status = identityGr.status.name.toString();
 vaVars.user_number = identityGr.number.toString();
 }
 } else {
 vaVars.guardian_user_sys_id = '';
 vaVars.user_name = '';
 vaVars.user_photo = '';
 vaVars.user_type = '';
 vaVars.user_status = '';
 vaVars.user_number = '';
 vaVars.user_type_sys_id ='';
 }

})()
