":"Reference","table":"sys_user","auto_select":false,"id":"current-user","name":"user","formatType":"text","secure":false,"sensitive":false,"aiInput":false,"list":false},{"type":"String","name":"user_email","list":false,"id":"609743e663684bc486f96826fa75c6a7","formatType":"text","metadata":{"libraryMappingType":"input"},"secure":false,"sensitive":false,"aiInput":false}],"applicability":{"type":"Applicability","mode":"script","value":"true"},"roles":[],"scope":"4c2b85dceb3f6610e4a8f1b4cad0cd2f","library-usage":{"type":"Library","input-parameters":[{"name":"user_email","label":"user_email","default-value":"""","required":true,"metadata":{"type":"String","list":false,"items":[],"use_items":false},"id":"609743e663684bc486f96826fa75c6a7","type":"String","hint":"User Email"}],"return-values-mapping":[{"name":"guardian_identity_gr","label":"Guardian_Identity_GR","value":{"type":"String","mode":"string","value":"{{vaVars.guardian_user_sys_id}}"}},{"name":"guardian_user_name","label":"Guardian_User_Name","value":{"type":"String","mode":"string","value":"{{vaVars.user_name}}"}},{"name":"guardian_user_type","label":"Guardian_User_Type","value":{"type":"String","mode":"string","value":"{{vaVars.user_type}}"}},{"name":"guardian_user_status","label":"Guardian_User_Status","value":{"type":"String","mode":"string","value":"{{vaVars.user_status}}"}},{"name":"guardian_user_photo","label":"Guardian_User_Photo","value":{"type":"String","mode":"string","value":"{{vaVars.user_photo}}"}},{"name":"guardian_user_number","label":"Guardian_User_Number","value":{"type":"String","mode":"string","value":"{{vaVars.user_number}}"}},{"name":"guardian_user_type_sys_id","label":"Guardian_user_type_sys_id","value":{"type":"String","mode":"string","value":"{{vaVars.user_type_sys_id}}"}}]},"domain":"global","topic_type":"TOPIC_BLOCK","channels":[],"dialog_acts_enabled":false,"id":"2900e4a72b3fee10d4dffd74ce91bfe8","name":"Guardian User Information Retriever","key_phrases":[],"nlu_provider":"","nlu_model":"","nlu_model_label":"","nlu_intent":"","nlu_intent_label":"","flexible_conversation_switching":true,"autopilot_topic":false,"design_categories":[],"triggerable_by_notification":false,"description":"This topic block is designed to identify whether a user exists within the system. If the user is found, it returns the relevant user details, including their unique identifier.

We use this block to provide flexibility in handling user data—whether through direct record lookup, invoking a skill, or triggering a sub flow for real-time integrations when needed.","model_type":"llm","foundational":false,"modify_confirmation_enabled":false,"context_profiles":[],"title":"Guardian User Information Retriever","library":true,"csTopicId":"64f7a8e72b7fee10d4dffd74ce91bf83","readOnly":false,"nluMapping":"[]"}

